    for r in range(H):
        for c in range(W):
            if gi[r][c]!=0 and not seen[r][c]:
                stack=[(r,c)]; comp=[]
                while stack:
                    y,x=stack.pop()
                    if seen[y][x]: continue
                    seen[y][x]=True; comp.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y+dy,x+dx
                            if (dy or dx) and 0<=ny<H and 0<=nx<W and gi[ny][nx]==gi[r][c] and not seen[ny][nx]:
                                stack.append((ny,nx))
                objs.append(comp)
    g=[[0]*W for _ in range(H)]
    if anchor_dir=='row':
        for obj in objs:
            rs=[y for y,_ in obj]
            top=min(rs); h=max(rs)-top+1
            # fall: shift down until bottom touches anchor-1 or cell below occupied(8-conn)
            best=0
            for dr in range(H):
                ok=True; bb=top+h-1+dr
                if bb>=H-1: ok=False
                else:
                    for y,x in obj:
