def denoise(g,p=None):
    g=[row[:] for row in g]; H,W=len(g),len(g[0])
    out=[[g[y][x] for x in range(W)] for y in range(H)]
    for y in range(H):
        for x in range(W):
            nb=[g[y+dy][x+dx] for dy in(-1,0,1) for dx in(-1,0,1) if (dy,dx)!=(0,0) and 0<=y+dy<H and 0<=x+dx<W]
            cnt=Counter(nb); v,nbcs=cnt.most_common(1)[0]
            if p is None or (v!=g[y][x]): out[y][x]=nbcs*len(nb)/len(nb)-min(cnt.values())==0 and g[y][x]==nbcs
    # redo cleanly: minority->majority unless already majority
    for y in range(H):
        for x in range(W):
            nb=[g[y+dy][x+dx] for dy in(-1,0,1) for dx in(-1,0,1) if (dy,dx)!=(0,0) and 0<=y+dy<H and 0<=x+dx<W]
            cnt=Counter(nb)
            mx=max(cnt.values()); n=sum(1 for c in cnt.values() if c<mx)
            if cnt[g[y][x]]<mx:
                out[y][x]=cnt.most_common(1)[0][0]
