                    ny,nx=y+dy,x+dx
                    if 0<=ny<H and 0<=nx<W and (ny,nx) not in seen and g[ny][nx]==v:
                        seen.add((ny,nx)); q.append((ny,nx))
            res.append((v,cp))
    return res
def solve(g, met='man', tieb=None, excbg=True):
    H,W=len(g),len(g[0])
    cs=comps(g)
    bg=Counter(v for row in g for v in row).most_common(1)[0][0]
    others=[(v,cp) for v,cp in cs if len(cp)>1 and (not excbg or v!=bg)]
    singles=[(cp[0],v) for vv,cp in cs if len(cp)==1]
    out=[r[:] for r in g]
    df={'man':lambda p,b:min(abs(p[0]-y)+abs(p[1]-x) for y,x in b),
        'cheb':lambda p,b:min(max(abs(p[0]-y),abs(p[1]-x)) for y,x in b)}
    def sortkey(t):
        s=t[2] if tieb=='small' else (-t[2] if tieb=='big' else 0)
        return (t[0],s)
    for (r,c),vv in singles:
        cands=[]
        for v2,cp2 in others:
            dd=df[met]((r,c),cp2); sz=len(cp2)
            cands.append((dd,sz,v2))
        cands.sort(key=sortkey)
        d_,s_,v2=cands[0]
        nb=[g[y][x] for dy in(-1,0,1) for dx in(-1,0,1)
            if (dy or dx) and 0<=r+dy<H and 0<=c+dx<W]
        cnt=Counter(nb)
        mx=max(cnt.values()); real=[v for v,k in cnt.items() if k>=mx and v!=vv]
        maj=real[0] if real else cnt.most_common(1)[0][0]
        out[r][c]= maj if s_==0 else v2
    return out
